 TextBlock FooterCell(Grid parent,int col,string title,string value){
  var cell=new Grid{Height=34,VerticalAlignment=VerticalAlignment.Center};footerCells[col]=cell;
  for(int i=0;i<7;i++)cell.ColumnDefinitions.Add(new ColumnDefinition{Width=i==0||i==6?new GridLength(1,GridUnitType.Star):GridLength.Auto});
