  System.Windows.Documents.Typography.SetNumeralAlignment(number,FontNumeralAlignment.Tabular);Grid.SetColumn(number,3);cell.Children.Add(number);
  FrameworkElement plot;
  if(col==0){footerCpu=new MiniSpark();plot=footerCpu;cpuDetail=Theme.Text("",12,Theme.Muted);cpuDetail.Visibility=Visibility.Collapsed;cell.Children.Add(cpuDetail);}
  else if(col==1){footerGpu=new GpuMini();plot=footerGpu;gpuDetail=Theme.Text("",12,Theme.Muted);gpuDetail.Visibility=Visibility.Collapsed;cell.Children.Add(gpuDetail);}
  else{memoryDetail=Theme.Text("",12,Theme.Muted);memoryDetail.Visibility=Visibility.Collapsed;cell.Children.Add(memoryDetail);footerMemory=new PixelMeter(0,Theme.Green,5){Blocks=16,VerticalAlignment=VerticalAlignment.Center};plot=footerMemory;}
