 }
 static void CenterFooterInk(TextBlock text,string sample){
  var ft=new FormattedText(sample,System.Globalization.CultureInfo.CurrentUICulture,FlowDirection.LeftToRight,new Typeface(text.FontFamily,text.FontStyle,text.FontWeight,text.FontStretch),text.FontSize,Brushes.Black,1);
  var ink=ft.BuildGeometry(new Point()).Bounds;if(!ink.IsEmpty)text.RenderTransform=new TranslateTransform(0,ft.Height/2-(ink.Top+ink.Height/2));
 }
 void LayoutFooterCell(int col){
  var cell=footerCells[col];if(cell==null||CpuValue==null||MemoryValue==null||DiskValue==null)return;
  var parent=cell.Parent as Grid;if(parent==null||parent.ActualWidth<=0)return;double available=parent.ColumnDefinitions[col].ActualWidth;if(available<=0)return;cell.Width=available;
  bool dense=available<248;double label=32,gap=dense?8:12,number=dense?108:116,plot=dense?Math.Max(24,Math.Min(48,available-label-number-2*gap)):72;
  cell.ColumnDefinitions[1].Width=new GridLength(label);cell.ColumnDefinitions[2].Width=new GridLength(gap);cell.ColumnDefinitions[3].Width=new GridLength(number);cell.ColumnDefinitions[4].Width=new GridLength(gap);cell.ColumnDefinitions[5].Width=new GridLength(plot);
  var value=col==0?CpuValue:col==1?DiskValue:MemoryValue;value.FontSize=dense?18:21;
  var title=(TextBlock)cell.Children[0];CenterFooterInk(title,title.Text);CenterFooterInk(value,col==2?"1000.0 GiB":"100.0%");
  if(col==0)footerCpu.Width=plot;else if(col==1)footerGpu.Width=plot;else footerMemory.Width=plot;
 }


